using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PulseEffect", menuName = "Data/Battle/Effects/Pulse Effect")]
public class PulseEffect : Effect
{
	[SerializeField]
	private bool corruptionPulse;

	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	[Header("Description")]
	[SerializeField]
	private BattleAction battleAction;

	[Header("Corruption Increase")]
	[SerializeField]
	[HideIf("corruptionPulse")]
	private bool increaseCorruptionReceived;

	[SerializeField]
	[ShowIf("increaseCorruptionReceived")]
	private Effect tormentEffect;

	[SerializeField]
	[ShowIf("increaseCorruptionReceived")]
	private bool enableIncreaseCorruptionReceivedFixedAmount;

	[SerializeField]
	[ShowIf("enableIncreaseCorruptionReceivedFixedAmount")]
	private int increaseCorruptionReceivedFixedAmount;

	public bool IncreaseCorruptionReceived => increaseCorruptionReceived;

	public bool EnableIncreaseCorruptionReceivedFixedAmount => enableIncreaseCorruptionReceivedFixedAmount;

	public int IncreaseCorruptionReceivedFixedAmount => increaseCorruptionReceivedFixedAmount;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string localizedAtTheStartOfItsTurn = base.localizationManager.GetLocalizedAtTheStartOfItsTurn(withSpace: true);
		string actionDescription = battleAction.GetActionDescription(amount);
		return string.Concat(localizedAtTheStartOfItsTurn + actionDescription, GetIncreaseCorruptionReceivedDescription(amount), AppendedDescription());
	}

	private string GetIncreaseCorruptionReceivedDescription(int amount)
	{
		if (increaseCorruptionReceived)
		{
			int amount2 = (enableIncreaseCorruptionReceivedFixedAmount ? increaseCorruptionReceivedFixedAmount : amount);
			return "\n" + tormentEffect.GetEffectDescription(amount2);
		}
		return "";
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueNefariousPulseDischargeRuinAction(PulseCoroutine(effectAmount, effectOwner));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	private IEnumerator PulseCoroutine(int effectAmount, GameObject effectOwner)
	{
		yield return new WaitForSeconds(0.2f);
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		yield return new WaitForSeconds(0.5f);
		SpawnVFX(GetVFXOwnerPosition(effectOwner), 5f);
		if (IsVFXEnabled())
		{
			PlayEffectActivationSFX();
		}
		List<GameObject> list = currentActiveUnits.GetCurrentActiveUnits();
		for (int i = 0; i < list.Count; i++)
		{
			CorruptionStats component = list[i].GetComponent<CorruptionStats>();
			if (corruptionPulse)
			{
				component.Corrupt(effectAmount, null);
			}
			else
			{
				component.Purify(effectAmount, null);
			}
		}
		yield return new WaitForSeconds(0.6f);
	}
}
